const vals = wb.getRange('Sheet1!A1:M1').getValues()[0] as number[];
const cols = 'ABCDEFGHIJKLM';
let count = 0, i = 0;
const hits: string[] = [];
while (i < vals.length) {
  const ref = vals[i];
  let j = i + 1, found = false;
  while (j < vals.length) {
    if (10 * vals[j] >= 11 * ref) { count++; hits.push(`${cols[i]}=${ref} -> ${cols[j]}=${vals[j]}`); found = true; break; }
    j++;
  }
  if (!found) break;
  i = j + 1;
}
log(hits.join('; '), 'count', count);
wb.getRange('Sheet1!B6').setValue(count);
const c = wb.getRange('Sheet1!B6').getCell();
log('B6', c.getValue(), c.getText(), typeof c.getValue());
log('L26:SHA26 count', wb.getRange('Sheet1!L26:SHA26').getCounts());

